using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);
var errors = build.FindChildrenRecursive<Error>();
foreach (var e in errors)
{
    Console.WriteLine($"[ERROR] {e.File}({e.LineNumber},{e.ColumnNumber}): {e.Code}: {e.Text}");
    // Try to get parent project
    var node = e.Parent;
    while (node != null && node is not Project)
        node = node.Parent;
    if (node is Project p)
        Console.WriteLine($"        Project: {p.Name}");
    Console.WriteLine();
}

var warnings = build.FindChildrenRecursive<Warning>().Where(w => !w.Code?.StartsWith("MSB4276") ?? true);
foreach (var w in warnings.Take(20))
{
    Console.WriteLine($"[WARN]  {w.File}({w.LineNumber},{w.ColumnNumber}): {w.Code}: {w.Text}");
}
EOF

