{
    var node = e.Parent;
    while (node != null && node is not Project)
        node = node.Parent;
    var proj = node as Project;
    Console.WriteLine($"  [{proj?.Name ?? "?"}] {e.File}({e.LineNumber},{e.ColumnNumber}): {e.Code}: {e.Text}");
}
EOF
